"""
RSA-Signed JWT Token API with Redis Blacklist
FastAPI server providing authentication endpoints
"""

import os
import json
import logging
from datetime import datetime, timedelta
from typing import Optional, Dict, Any

from fastapi import FastAPI, HTTPException, Request
from jose import jwt, JWTError
from cryptography.hazmat.primitives import serialization
import redis
import bcrypt

# Configure logging
os.makedirs('/app/logs', exist_ok=True)
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('/app/logs/app.log'),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)

app = FastAPI(title="JWT Token API with Redis Blacklist")

# Load RSA keys
with open('/app/keys/public.pem', 'rb') as f:
    public_key_pem = f.read()
with open('/app/keys/private.pem', 'rb') as f:
    private_key_pem = f.read()
public_key = serialization.load_pem_public_key(public_key_pem)

# Redis connection
redis_client = redis.Redis(host='localhost', port=6379, decode_responses=True)
try:
    redis_client.ping()
    logger.info("Redis connection successful")
except Exception as e:
    logger.error(f"Redis connection failed: {e}")
    raise

USERS = {'admin': bcrypt.hashpw(b'password123', bcrypt.gensalt()).decode('utf-8')}
ACCESS_TOKEN_EXPIRE_MINUTES = 15
REFRESH_TOKEN_EXPIRE_DAYS = 7
ALGORITHM = "RS256"
ISSUER = "jwt-token-api"

def create_access_token(sub: str, jti: str = None) -> str:
    now = datetime.utcnow()
    expire = now + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    payload = {"iss": ISSUER, "sub": sub, "exp": int(expire.timestamp()), "iat": int(now.timestamp())}
    if jti is None:
        import secrets
        jti = secrets.token_hex(16)
        payload["jti"] = jti
    return jwt.encode(payload, private_key_pem, algorithm=ALGORITHM)

def create_refresh_token(sub: str, jti: str = None) -> str:
    now = datetime.utcnow()
    expire = now + timedelta(days=REFRESH_TOKEN_EXPIRE_DAYS)
    payload = {"iss": ISSUER, "sub": sub, "exp": int(expire.timestamp()), "iat": int(now.timestamp())}
    if jti is None:
        import secrets
        jti = secrets.token_hex(16)
        payload["jti"] = jti
    return jwt.encode(payload, private_key_pem, algorithm=ALGORITHM)

def decode_and_verify_token(token: str) -> Dict[str, Any]:
    try:
        payload = jwt.decode(token, public_key, algorithms=[ALGORITHM])
        jti = payload.get("jti")
        if jti:
            blacklist_key = f"blacklist:{jti}"
            if redis_client.exists(blacklist_key):
                logger.warning(f"Token with JTI {jti} is revoked")
                raise HTTPException(status_code=403, detail="Token has been revoked")
        return payload
    except JWTError as e:
        logger.error(f"JWT error: {e}")
        if "exp" in str(e).lower():
            raise HTTPException(status_code=401, detail="Token has expired")
        raise HTTPException(status_code=401, detail="Invalid or expired token")
    except Exception as e:
        logger.error(f"Token error: {e}")
        raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/auth/login")
async def login(request: dict):
    username = request.get("username", "")
    password = request.get("password", "")
    if username not in USERS:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if not bcrypt.checkpw(password.encode('utf-8'), USERS[username].encode('utf-8')):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    logger.info(f"User {username} logged in")
    return {"access_token": create_access_token(username), "refresh_token": create_refresh_token(username), "token_type": "bearer"}

@app.post("/auth/refresh")
async def refresh_tokens(request: dict):
    refresh_token = request.get("refresh_token", "")
    payload = decode_and_verify_token(refresh_token)
    sub = payload.get("sub")
    if not sub:
        raise HTTPException(status_code=401, detail="Invalid refresh token")
    return {"access_token": create_access_token(sub), "token_type": "bearer"}

@app.post("/auth/revoke")
async def revoke_token(request: dict):
    token = request.get("token", "")
    try:
        payload = jwt.decode(token, public_key, algorithms=[ALGORITHM])
        jti = payload.get("jti")
        exp = payload.get("exp")
    except JWTError:
        raise HTTPException(status_code=400, detail="Invalid token")
    if not jti or not exp:
        raise HTTPException(status_code=400, detail="Token missing required claims")
    blacklist_key = f"blacklist:{jti}"
    ttl = int(exp - datetime.utcnow().timestamp())
    if ttl > 0:
        redis_client.setex(blacklist_key, ttl, "revoked")
        logger.info(f"Token {jti} revoked, TTL={ttl}")
    return {"status": "success", "message": "Token revoked"}

@app.get("/auth/validate")
async def validate_token(request: Request):
    auth_header = request.headers.get("Authorization")
    if not auth_header or not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Missing or invalid Authorization header")
    token = auth_header[7:]
    payload = decode_and_verify_token(token)
    return {"valid": True, "user": payload.get("sub"), "jti": payload.get("jti"), "message": "Token is valid"}

@app.get("/health")
async def health_check():
    return {"status": "healthy", "redis": "connected" if redis_client.ping() else "disconnected"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
